import { Subject, } from 'rxjs';
import { AbortSignalAction, } from 'lib/sys/abort-signal-action';
export class SerialDataSource {
    #subject = new Subject();
    subscribe(observer, options) {
        const { abort_signal, once, } = (options ?? {});
        abort_signal?.throwIfAborted();
        let subscription;
        let unsubscribed = false;
        const subscription_observer = once
            ? (value) => {
                if (!unsubscribed) {
                    unsubscribed = true;
                    subscription?.unsubscribe(); // note: subscription is not undefined
                }
                observer(value);
            }
            : observer;
        subscription = this.#subject.subscribe(subscription_observer);
        const abort_signal_action = new AbortSignalAction(abort_signal, () => { subscription.unsubscribe(); });
        const unsubscribe = () => {
            abort_signal_action.trigger();
        };
        return {
            abort_signal,
            unsubscribe,
        };
    }
    dispatch(data) {
        this.#subject.next(data);
    }
}
