                            & > div {
                                background-color: var(--theme-si-hb, hotpink);
                            }
                        }
                        &[aria-selected="false"]:hover {
                            & > div {
                                background-color: var(--theme-si-vb, hotpink);
                            }
                        }
                    }
                    [data-numeric]:not([data-numeric=""]) {
                        text-align: right;
                        padding-right: 1em;  /* make column look less crowded to the right, especially with the left-justified headings */
                    }
                }

                .server-fs-dialog-file-list-header-container,
                .server-fs-dialog-file-list-content-container {
                    & > div {
                        padding: var(--server-fs-dialog-content-padding);
                    }
                }
            }
        }

        .server-fs-dialog-file-list-controls-footer {
            justify-self: end;
            align-content: end;
            box-sizing: border-box;  /* make --server-fs-dialog-footer-height encompass border, padding, etc */
            height: var(--server-fs-dialog-footer-height);
            padding: var(--server-fs-dialog-footer-padding);

            & > button {
                margin: 0.25em;
                user-select: none;
                border-radius: 5px;
            }
        }
    }

    /* cancel is the default when focused, otherwise submit is the default,
     * however no button is default when the the file list rows are selected
     */
    button.server-fs-dialog-files-form-cancel-button:focus,
    &:not(:has(.server-fs-dialog-file-list-content-container:focus-within)) button.server-fs-dialog-files-form-cancel-button:not(:focus) ~ button.server-fs-dialog-files-form-submit-button {
        outline: 1px solid var(--theme-si-fg, hotpink);
        outline-offset: 2px;
    }
}


:root[data-theme="dark"] .server-fs-dialog img.dark {
    display: inline;
}
:root[data-theme="dark"] .server-fs-dialog img.light {
    display: none;
}
:root:not([data-theme="dark"]) .server-fs-dialog img.dark {
    display: none;
}
:root:not([data-theme="dark"]) .server-fs-dialog img.light {
    display: inline;
}



/* === print media queries === */

@media not print {
    /* nothing for now */
}

@media print {

    header {
        display: none;
    }

    .notification-area {
        display: none;
    }

    main {
        overflow: visible;
    }

}
