og-border-size:     1px;\n\n    --server-fs-dialog-nav-height: calc(3*var(--server-fs-dialog-nav-row-height) + 2*var(--server-fs-dialog-nav-gap));\n\n    resize: both;\n    width:  min(100dvw, 1024px);\n    height: min(100dvh,  768px);\n    display: grid;\n    grid-template-rows:\n        var(--server-fs-dialog-nav-height)               /* directory chooser */\n        calc(100% - var(--server-fs-dialog-nav-height))  /* file list plus controls form */\n    ;\n\n    nav {\n        display: grid;\n        grid-template-columns: auto 1fr;\n        grid-auto-rows: var(--server-fs-dialog-nav-row-height);\n        align-items: center;\n        gap: var(--server-fs-dialog-nav-gap);\n\n        box-sizing: border-box;  /* make --server-fs-dialog-nav-height encompass border, padding, etc */\n        max-width: min(80ch, 90%);\n        height: var(--server-fs-dialog-nav-height);\n\n        ol.server-fs-dialog-directory-chooser {\n            /* override the standard spacing configuration for <ol> elements */\n            margin-block-start: 0;\n            margin-block-end: 0;\n            padding-inline-start: 0;\n            /* end of overrides */\n\n            li {\n                display: inline-block;\n                margin:  var(--server-fs-dialog-chooser-margin) 0.25em var(--server-fs-dialog-chooser-margin) 0em;\n                padding: 0.1em 0.25em;\n                list-style-type: none;\n\n                &[aria-checked=\"true\"] {\n                    background-color: var(--theme-si-hb, hotpink);\n\n                    &:not(:focus) {\n                        outline: 1px dotted var(--theme-si-fg, hotpink);\n                    }\n                }\n                &[aria-checked=\"false\"]:hover {\n                    background-color: var(--theme-si-vb, hotpink);\n                }\n\n                &:has(~ [aria-checked=\"true\"]),\n                &[aria-checked=\"true\"] {\n                    font-weight: bold;\n                }\n                [aria-checked=\"true\"] ~ & {\n                    font-style: italic;\n                }\n            }\n        }\n\n        .server-fs-dialog-directory-creator-holder img.icon {\n            padding: 0 0.25em 0 0.5em;\n        }\n\n        .server-fs-dialog-directory-creator-controls {\n            overflow: hidden;\n            max-width: 100%;\n            transition: max-width 2s;\n\n            & > * {\n                max-width: 100%;\n                transition: max-width 0s;\n            }\n            &:focus-within > * {\n                transition: max-width 2s;\n            }\n            &:not(:focus-within),\n            &:not(:focus-within) > * {\n                /* hide the controls but still permit focus */\n                max-width: 0px;\n                margin: 0;\n                padding: 0;\n                border: none;                \n                overflow: hidden;\n            }\n        }\n\n        input.server-fs-dialog-filename[type=\"text\"][readonly] {\n            /* when for_save is false, filename input is set to readonly */\n            border: none;\n            outline: none;\n        }\n    }\n\n    img.icon {\n        width:  1.2em;\n        height: 1.2em;\n        vertical-align: middle;\n    }\n\n    .server-fs-dialog-files-form {\n        display: grid;\n        grid-template-rows:\n            calc(100% - var(--server-fs-dialog-footer-height))  /* file list */\n            var(--server-fs-dialog-footer-height)               /* controls */\n        ;\n        height: 100%;\n\n        .server-fs-dialog-file-list-holder {\n            height: calc(100% - var(--server-fs-dialog-border-size));  /* account for bottom border */\n\n            .server-fs-dialog-file-list {\n                height: 100%;\n                font-family: 'monospace';\n\n                .server-fs-dialog-file-list-header-container,\n                .server-fs-dialog-file-list-content-container {\n                    display: grid;\n                    grid-template-columns:\n                        /* use fixed widths to make header and content columns be aligned */\n                        auto              /* type field (icon) -- using auto here will make the header and content columns be misaligned, but only a little */\n                        minmax(4em, 8fr)  /* name field */\n                        6em               /* size field */\n                        8em               /* modified field */\n                        5em               /* manipulation links */\n                    ;\n                    grid-auto-rows: max-content;\n                    overflow-y: scroll;\n                }\n\n                /* fr units by default have a min value of auto and this can result in\n                 * the header and content grids not aligning.  This can be fixed by\n                 * repacing Xfr with minmax(0, Xfr), but that kind of clutters the\n                 * grid-template-columns specification, so instead set min-width: 0\n                 * on all child divs (kind of brute force but it works...).\n                 */\n                .server-fs-dialog-file-list-header-container > div,\n                .server-fs-dialog-file-list-content-container > div > div {  /* note: content rows are wrapped in a div to allow for row selection */\n                    & > div {\n                        overflow: hidden;\n                    }\n                }\n\n                .server-fs-dialog-file-list-header-container {\n                    align-content: end;\n                    height: var(--server-fs-dialog-header-height);\n                    border-bottom: var(--server-fs-dialog-border-size) solid var(--theme-si-fg, hotpink);\n\n                    .server-fs-dialog-file-list-header,\n                    & > div {\n                        user-select: none;\n                        border-left: var(--server-fs-dialog-border-size) solid var(--theme-si-fg, hotpink);\n                    }\n              